<template><div class="page"><div class="page-title"><h2>沙盘模拟</h2><el-button type="primary" :disabled="!canWrite()" @click="create">创建场景</el-button></div><div class="grid-2"><div class="panel"><el-table :data="rows" stripe @row-click="select"><el-table-column prop="name" label="场景" /><el-table-column prop="status" label="状态" /><el-table-column prop="totalCost" label="总成本" /><el-table-column prop="serviceLevel" label="服务水平" /><el-table-column label="操作"><template #default="{row}"><el-button link @click.stop="run(row)">运行</el-button><el-button link type="primary" @click.stop="apply(row)">应用</el-button></template></el-table-column></el-table></div><div class="panel"><h3>{{ selected?.name || '选择一个场景查看结果' }}</h3><div v-if="selected" class="stats"><div class="stat"><div class="label">总成本</div><div class="value">{{ selected.totalCost }}</div></div><div class="stat"><div class="label">服务水平</div><div class="value">{{ selected.serviceLevel }}</div></div></div><Chart v-if="selected" :option="option" /></div></div><el-dialog v-model="dialog" title="创建沙盘场景"><el-form label-width="120px"><el-form-item label="场景名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="需求倍率"><el-input-number v-model="form.params.demandMultiplier" :min="0" :step="0.1" /></el-form-item><el-form-item label="分配策略"><el-select v-model="form.params.allocationStrategy"><el-option v-for="v in ['NEAREST','LOWEST_COST','BALANCED','SINGLE_WAREHOUSE']" :key="v" :label="v" :value="v" /></el-select></el-form-item><el-form-item label="补货提前期"><el-input-number v-model="form.params.replenishLeadDays" :min="0" /></el-form-item><el-form-item label="承运商比例"><el-input v-model="carrierJson" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import { computed, reactive, ref } from 'vue'; import { sandboxApi } from '../api'; import { canWrite } from '../auth'; import { ElMessage } from 'element-plus'; import Chart from '../components/Chart.vue'
const rows=ref([]),selected=ref(null),dialog=ref(false),carrierJson=ref('{"SF":0.4,"JDL":0.3,"SELF":0.3}'); const form=reactive({name:'新场景',params:{demandMultiplier:1,allocationStrategy:'NEAREST',replenishLeadDays:3,carrierMix:{SF:.4,JDL:.3,SELF:.3}}}); const option=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:(selected.value?.resultJson?[]:[])},yAxis:{type:'value'},series:[]})); async function load(){rows.value=await sandboxApi.page()}; async function create(){dialog.value=true}; async function save(){form.params.carrierMix=JSON.parse(carrierJson.value);await sandboxApi.create(form);dialog.value=false;load()}; async function run(row){await sandboxApi.run(row.id);await load()}; async function select(row){selected.value=await sandboxApi.get(row.id)}; async function apply(row){await sandboxApi.apply(row.id);ElMessage.success('已生成待执行动作')};load()
</script>
